// On-demand client inventory for map/zone visibility failures. It changes no
// replication or HUD state; run `VersusNetVisualAudit` in either client console.
function ServerReportVersusVisualAudit(string Details)
{
    Log("HPVersusClientVisualAudit reporter=" $ string(self)
        $ " detail=" $ Details);
}

exec function VersusNetVisualAudit()
{
    local HPVersusHarry H;
    local HPVersusPRI VPRI;
    local HPVersusHealthPickup HealthPickup;
    local HPVersusSpeedPickup SpeedPickup;
    local string CharacterName;
    local int RemoteCount;
    local int HealthCount;
    local int SpeedCount;

    Log("HPVersusNetVisualAudit observer=" $ string(self)
        $ " location=" $ string(Location)
        $ " zone=" $ string(Region.Zone));
    ServerReportVersusVisualAudit("observer slot=" $ string(VersusSlot)
        $ " location=" $ string(Location)
        $ " zone=" $ string(Region.Zone));
    foreach AllActors(Class'HPVersusHarry', H)
    {
        VPRI = HPVersusPRI(H.PlayerReplicationInfo);
        CharacterName = "None";
        if (VPRI != None)
            CharacterName = VPRI.SelectedCharacter;
        if (H != self)
            RemoteCount++;
        Log("HPVersusNetVisualAudit pawn=" $ string(H)
            $ " slot=" $ string(H.VersusSlot)
            $ " Role=" $ string(H.Role)
            $ " RemoteRole=" $ string(H.RemoteRole)
            $ " Player=" $ string(H.Player)
            $ " owner=" $ string(H.Owner)
            $ " Location=" $ string(H.Location)
            $ " zone=" $ string(H.Region.Zone)
            $ " hidden=" $ string(H.bHidden)
            $ " draw=" $ string(H.DrawType)
            $ " mesh=" $ string(H.Mesh)
            $ " scale=" $ string(H.DrawScale)
            $ " alwaysRelevant=" $ string(H.bAlwaysRelevant)
            $ " selected=" $ CharacterName);
        ServerReportVersusVisualAudit("pawn=" $ string(H)
            $ " slot=" $ string(H.VersusSlot)
            $ " location=" $ string(H.Location)
            $ " zone=" $ string(H.Region.Zone)
            $ " hidden=" $ string(H.bHidden)
            $ " draw=" $ string(H.DrawType)
            $ " mesh=" $ string(H.Mesh)
            $ " alwaysRelevant=" $ string(H.bAlwaysRelevant));
    }
    foreach AllActors(Class'HPVersusHealthPickup', HealthPickup)
    {
        HealthCount++;
        Log("HPVersusNetVisualAudit health=" $ string(HealthPickup)
            $ " Location=" $ string(HealthPickup.Location)
            $ " BaseLocation=" $ string(HealthPickup.BaseLocation)
            $ " baseReady=" $ string(HealthPickup.bBaseLocationReady)
            $ " delta=" $ string(VSize(HealthPickup.Location - HealthPickup.BaseLocation))
            $ " available=" $ string(HealthPickup.bAvailable)
            $ " hidden=" $ string(HealthPickup.bHidden)
            $ " collide=" $ string(HealthPickup.bCollideActors)
            $ " mesh=" $ string(HealthPickup.Mesh)
            $ " draw=" $ string(HealthPickup.DrawType)
            $ " Role=" $ string(HealthPickup.Role)
            $ " RemoteRole=" $ string(HealthPickup.RemoteRole));
        ServerReportVersusVisualAudit("health=" $ string(HealthPickup)
            $ " location=" $ string(HealthPickup.Location)
            $ " base=" $ string(HealthPickup.BaseLocation)
            $ " ready=" $ string(HealthPickup.bBaseLocationReady)
            $ " available=" $ string(HealthPickup.bAvailable)
            $ " hidden=" $ string(HealthPickup.bHidden));
    }
    foreach AllActors(Class'HPVersusSpeedPickup', SpeedPickup)
    {
        SpeedCount++;
        Log("HPVersusNetVisualAudit speed=" $ string(SpeedPickup)
            $ " Location=" $ string(SpeedPickup.Location)
            $ " BaseLocation=" $ string(SpeedPickup.BaseLocation)
            $ " baseReady=" $ string(SpeedPickup.bBaseLocationReady)
            $ " delta=" $ string(VSize(SpeedPickup.Location - SpeedPickup.BaseLocation))
            $ " available=" $ string(SpeedPickup.bAvailable)
            $ " hidden=" $ string(SpeedPickup.bHidden)
            $ " collide=" $ string(SpeedPickup.bCollideActors)
            $ " mesh=" $ string(SpeedPickup.Mesh)
            $ " draw=" $ string(SpeedPickup.DrawType)
            $ " Role=" $ string(SpeedPickup.Role)
            $ " RemoteRole=" $ string(SpeedPickup.RemoteRole));
        ServerReportVersusVisualAudit("speed=" $ string(SpeedPickup)
            $ " location=" $ string(SpeedPickup.Location)
            $ " base=" $ string(SpeedPickup.BaseLocation)
            $ " ready=" $ string(SpeedPickup.bBaseLocationReady)
            $ " available=" $ string(SpeedPickup.bAvailable)
            $ " hidden=" $ string(SpeedPickup.bHidden));
    }
    ClientMessage("VISUAL AUDIT remote=" $ RemoteCount
        $ " health=" $ HealthCount $ " speed=" $ SpeedCount);
    ServerReportVersusVisualAudit("summary remote=" $ RemoteCount
        $ " health=" $ HealthCount $ " speed=" $ SpeedCount);
}

